const RL_MAP=new Map();
function rl(key, limit, windowMs){
  const now=Date.now();
  const e=RL_MAP.get(key);
  if(!e||now-e.start>windowMs){ RL_MAP.set(key,{start:now,count:1}); return true; }
  e.count+=1;
  if(e.count>limit) return false;
  return true;
}
```

Call it before doing any work:

```js
